const lines = csvData.trim().split('\n');
const headers = lines[0].split(',');
const products = lines.slice(1).map(line => {
  const values = line.split(',');
  const product = {};
  headers.forEach((header, i) => {
    product[header.trim().toLowerCase().replace(/ /g, '_')] = values[i] ? values[i].trim() : '';
  });
  return product;
});

const query = $input.first().json.query || '';
const queryLower = query.toLowerCase();
let results = [...products];

const underMatch = queryLower.match(/(?:under|niche|er\s+niche|er\s+kom|theke\s+kom|within)\s*(\d+)/);
const aboveMatch = queryLower.match(/(?:above|upore|er\s+upore|over|er\s+beshi)\s*(\d+)/);
const rangeMatch = queryLower.match(/(\d+)\s*(?:theke|to|-)\s*(\d+)/);

if (underMatch) {
  const maxPrice = parseInt(underMatch[1]);
  results = results.filter(p => parseInt(p.price) <= maxPrice);
}
if (aboveMatch) {
  const minPrice = parseInt(aboveMatch[1]);
  results = results.filter(p => parseInt(p.price) >= minPrice);
}
if (rangeMatch) {
  const min = parseInt(rangeMatch[1]);
  const max = parseInt(rangeMatch[2]);
  results = results.filter(p => {
    const price = parseInt(p.price);
    return price >= min && price <= max;
  });
}

const cleanQuery = queryLower
  .replace(/\b(er|dam|koto|price|phone|ache|ki|ta|gulo|dekhao|show|niche|under|above|upore|theke|budget|kena|kinte|chai)\b/g, '')
  .trim();

if (cleanQuery && cleanQuery.length > 1) {
  const searchTerms = cleanQuery.split(/\s+/).filter(t => t.length > 1);
  if (searchTerms.length > 0) {
    results = results.filter(p => {
      const searchText = Object.values(p).join(' ').toLowerCase();
      return searchTerms.every(term => searchText.includes(term));
    });
  }
}

if (results.length === 0) {
  return 'No products found matching your search. Try a different search term, brand name, or price range.';
}

const formatted = results.slice(0, 10).map((p, i) => {
  return `${i + 1}. ${p.name} | Brand: ${p.brand} | Storage: ${p.storage} | Color: ${p.color} | Price: ৳${parseInt(p.price).toLocaleString()} | Stock: ${p.stock_status}`;
}).join('\n');

const summary = `Found ${results.length} product(s)${results.length > 10 ? ' (showing top 10)' : ''}:\n${formatted}`;
return summary;
